import 'core-js';
import React from 'react';
import ReactDOM from 'react-dom';
import { BrowserRouter } from 'react-router-dom';
import App from './App';
import { config } from "./utils/log";
import { setupGuidesRenderer } from './utils/helper';

import defaultTheme from './theme/defaultTheme';
import buildComponentPalette, { buildChatTranscriptorPalette } from './theme/componentPalette';
import packageJson from '../package.json';

function getBrandInfo() {
  if (typeof window === 'undefined') {
    return null;
  }
  if (window.__CHAT_BRAND_INFO__) {
    return window.__CHAT_BRAND_INFO__;
  }
  // The widget is typically rendered inside the vendor's iframe, which never
  // loads brandInfo.js itself - only the host page does. Fall back to the
  // parent window's copy (same pattern Chat.js uses for header colors).
  try {
    if (window.parent && window.parent !== window && window.parent.__CHAT_BRAND_INFO__) {
      return window.parent.__CHAT_BRAND_INFO__;
    }
  } catch (e) {
    // window.parent is cross-origin; brand info isn't reachable
  }
  return null;
}

function getUtagDataInfo() {
  if (typeof window === 'undefined') {
    return null;
  }
  if (window.utag_data) {
    return window.utag_data;
  }
  // The widget is typically rendered inside the vendor's iframe, which never
  // loads brandInfo.js itself - only the host page does. Fall back to the
  // parent window's copy (same pattern Chat.js uses for header colors).
  try {
    if (window.parent && window.parent !== window && window.parent.utag_data) {
      return window.parent.utag_data;
    }
  } catch (e) {
    // window.parent is cross-origin; utag_data isn't reachable
  }
  return null;
}

function resolveFontFaces(brandConfig) {
  const fontFaces = brandConfig.fontFaces;
  if (!Array.isArray(fontFaces) || !fontFaces.length) {
    return [];
  }

  let baseHref = window.location.href;
  try {
    if (window.parent && window.parent !== window) {
      baseHref = window.parent.location.href;
    }
  } catch (e) {
    // window.parent is cross-origin; resolve font URLs against our own document instead
  }

  return fontFaces.map(face => ({ ...face, url: new URL(face.url, baseHref).href }));
}

function buildThemeConfig(brandConfig = {}) {
  const themeConfig = {};
  const colors = brandConfig.colors || {};
  console.log("Brand colors:", colors);
  console.log("Chat palette:", buildChatTranscriptorPalette(colors));

  // colors.primary500 already carries prepare-brand.js's own fallback chain
  // (colors.json -> widget.primaryColor -> hardcoded default), so reading
  // it here is safe even for brands that haven't set up colors.json yet.
  const primary = colors.primary500;
  const secondary = (colors.secondary && colors.secondary['500']) || brandConfig.secondaryColor;

  if (primary || secondary) {
    themeConfig.color = {};
    if (primary) {
      themeConfig.color.primary = primary;
    }
    if (secondary) {
      themeConfig.color.secondary = secondary;
    }
    // Full colors.json scale, plus the readable per-UI-area tokens built
    // from it - the single place every component's color should come from.
    themeConfig.colors = colors;
    themeConfig.componentPalette = buildComponentPalette(colors);
    // Keeps the direct-embed render path (theme.chatTranscriptor) in sync
    // with the hosted-widget iframe path (brand-theme.css's CSS vars) -
    // both now resolve from the same colors.json bubbles.* keys instead of
    // this path silently falling back to defaultTheme's hardcoded colors.
    themeConfig.chatTranscriptor = {
      ...defaultTheme.chatTranscriptor,
      ...buildChatTranscriptorPalette(colors),

    };
  }

  if (brandConfig.fontFamily) {
    themeConfig.globals = {
      ...defaultTheme.globals,
      bodyFontFamily: brandConfig.fontFamily,
    };

    themeConfig.fonts = Object.keys(defaultTheme.fonts).reduce((fonts, key) => {
      fonts[key] = brandConfig.fontFamily;
      return fonts;
    }, {});
  }

  return themeConfig;
}

function buildHeaderConfig(brandConfig = {}) {
  const headerConfig = {};
  if (brandConfig.title) {
    headerConfig.title = brandConfig.title;
  }
  if (brandConfig.subtitle) {
    headerConfig.subtitle = brandConfig.subtitle;
  }
  return headerConfig;
}

function buildDisclaimerConfig(brandConfig = {}, countryCode = 'us') {
  const disclaimerConfig = {};
  const disclaimer = brandConfig.disclaimer || {};
  if (disclaimer.privacyPolicyUrl) {
    disclaimerConfig.privacyPolicyUrl = disclaimer.privacyPolicyUrl[countryCode];
  }
  if (disclaimer.termsOfUseUrl) {
    disclaimerConfig.termsOfUseUrl = disclaimer.termsOfUseUrl[countryCode];
  }
  if (disclaimer.consumerHealthDataPrivacyStatementUrl) {
    disclaimerConfig.consumerHealthDataPrivacyStatementUrl = disclaimer.consumerHealthDataPrivacyStatementUrl[countryCode];
  }
  if (disclaimer.disclaimerMessage) {
    disclaimerConfig.disclaimerMessage = disclaimer.disclaimerMessage[countryCode];
  }
  return disclaimerConfig;
}

function buildLogoConfig(brandInfo) {
  if (brandInfo && brandInfo.assets && brandInfo.assets.logo) {
    return {
      sourceUrl: brandInfo.assets.logo,
      altText: `${brandInfo.brand || 'Brand'} logo`,
    };
  }
  return {};
}

(function (connect) {
  connect.LogManager && connect.LogManager.updateLoggerConfig(config);
  connect.ChatInterface = connect.ChatInterface || {};
  connect.ChatInterface.init = ({ containerId, ...props }) => {
    const brandInfo = getBrandInfo();
    const brandConfig = brandInfo?.config || {};

    // Build brand theme
    const brandThemeConfig = buildThemeConfig(brandConfig);

    console.log("========== THEME DEBUG ==========");
    console.log("Brand Theme:", brandThemeConfig.chatTranscriptor);
    console.log("Caller Theme Override:", props.themeConfig?.chatTranscriptor);
    const themeConfig = {
      ...brandThemeConfig,
      ...props.themeConfig,
      chatTranscriptor: {
        ...brandThemeConfig.chatTranscriptor,
      },
    };
    // Use the default chatTranscriptor
    //themeConfig.chatTranscriptor = defaultTheme.chatTranscriptor;

    console.log("Merged Theme:", themeConfig.chatTranscriptor);
    console.log(
      "Final outgoingMsgBg:",
      themeConfig.chatTranscriptor?.outgoingMsgBg
    );
    console.log("=================================");

    const headerConfig = Object.assign(
      {},
      buildHeaderConfig(brandConfig),
      props.headerConfig || {}
    );

    const logoConfig = Object.assign(
      {},
      buildLogoConfig(brandInfo),
      props.logoConfig || {}
    );

    const utagData = getUtagDataInfo();

    const disclaimerConfig = Object.assign(
      {},
      buildDisclaimerConfig(brandConfig, utagData?.country_code),
      props.disclaimerConfig || {}
    );

    const fontFaces = resolveFontFaces(brandConfig);

    if (props.widgetType) {
      config.csmConfig = {
        widgetType: props.widgetType
      };
    }
    config.features = {
      messageReceipts: {
        shouldSendMessageReceipts: true,
        throttleTime: 5000
      }
    };
    config.customUserAgentSuffix = `AmazonConnect-ChatInterface/${packageJson.version}`;
    connect.ChatSession.setGlobalConfig(config);

    setupGuidesRenderer(props);

    ReactDOM.render(
      <BrowserRouter>
        <App
          {...props}
          themeConfig={themeConfig}
          headerConfig={headerConfig}
          logoConfig={logoConfig}
          disclaimerConfig={disclaimerConfig}
          fontFaces={fontFaces}
        />
      </BrowserRouter>,
      document.getElementById(containerId) ||
      document.getElementById("root")
    );
  };

  connect.ChatInterface.getCurrentTheme = () => {
    const brandInfo = getBrandInfo();
    return Object.assign(
      {},
      defaultTheme,
      buildThemeConfig(brandInfo?.config || {})
    );
  };

  window.connect = connect;
}(window.connect || {}));

