import {
  Status,
  Direction,
  ItemDetails,
  TransportDetails,
  ContentType,
  PARTICIPANT_TYPES,
  PARTICIPANT_MESSAGE,
  ATTACHMENT_MESSAGE,
  InteractiveMessageType,
  AttachmentStatus,
} from "./Model";

function isRecognizedEvent(eventName) {
  var values = Object.values(ContentType.EVENT_CONTENT_TYPE);
  for (var index = 0; index < values.length; index++) {
    if (values[index] === eventName) {
      return true;
    }
  }
  return false;
}

function getContent(item) {
  var content = {};
  content.data = item.Content;
  content.type = item.ContentType;
  return content;
}

function createItemFromIncoming(item, thisParticipant) {
  var transcriptItem = new ItemDetails();
  var transportDetails = new TransportDetails();
  transcriptItem.id = item.Id;
  transcriptItem.type = item.Type;
  transcriptItem.content = getContent(item);
  transcriptItem.displayName = item.DisplayName;
  transcriptItem.participantId = item.ParticipantId;
  transcriptItem.participantRole = item.ParticipantRole;
  transportDetails.direction = 
      item.ParticipantRole === PARTICIPANT_TYPES.CUSTOMER
        ? Direction.Outgoing
        : Direction.Incoming;
  transportDetails.sentTime = 
    new Date(item.AbsoluteTime).getTime() / 1000;
  transportDetails.status = Status.SendSuccess;
  if (item.MessageMetadata && Array.isArray(item.MessageMetadata.Receipts) && item.MessageMetadata.Receipts.length > 0) {
    const receipt = item.MessageMetadata.Receipts.find(receipt => receipt.RecipientParticipantId !== transcriptItem.participantId) || {};
    transportDetails.messageReceiptType =  receipt.ReadTimestamp ? "read" : (receipt.DeliveredTimestamp ? "delivered" : "");
  }
  if (item.MessageMetadata && item.MessageMetadata.MessageCompleted !== null && item.MessageMetadata.MessageCompleted !== undefined) {
    transcriptItem.messageCompleted = item.MessageMetadata.MessageCompleted;
  }
  transcriptItem.transportDetails = transportDetails;
  transcriptItem.version = 0;
  transcriptItem.Attachments = item.Attachments;
  transcriptItem.isOldConversation = !!item.RelatedContactid;
  return transcriptItem;
}

function createTranscriptItemFromSuccessResponse(oldTranscriptItem, response) {
  const newTranscriptItem = new ItemDetails();
  Object.assign(newTranscriptItem, oldTranscriptItem);

  if(response.data && response.data.Id){
    newTranscriptItem.id = response.data.Id;
  }

  newTranscriptItem.transportDetails = {
    ...oldTranscriptItem.transportDetails,
    status: Status.SendSuccess,
    sentTime: new Date(response.data.AbsoluteTime || Date.now()).getTime() / 1000
  };
  return newTranscriptItem;
}

function createOutgoingTranscriptItem(type, content, participant){
  const transcriptItem = new ItemDetails();
  const transportDetails = {};
  transcriptItem.type = type;
  transcriptItem.content = content;
  transcriptItem.participantId = participant.participantId;
  transcriptItem.participantRole = PARTICIPANT_TYPES.CUSTOMER;
  transcriptItem.displayName = participant.displayName;
  transportDetails.status = Status.Sending;
  transportDetails.direction = Direction.Outgoing;
  transportDetails.sentTime = _timestampNow();
  transcriptItem.transportDetails = transportDetails;
  transcriptItem.id = _generateLocalId();
  transcriptItem.version = 0;
  return transcriptItem;
}

function createFailedItem(item, sentTime) {
  const clonedItem = new ItemDetails(item);
  clonedItem.transportDetails.status = Status.SendFailed;
  clonedItem.transportDetails.sentTime = sentTime;
  clonedItem.version = clonedItem.version + 1;
  return clonedItem;
}

// Client-side-only re-display of the last incoming message, used by
// ChatSession's inactivity handling (see INACTIVITY_REPROMPT_DELAY_MS) to
// nudge a customer who's gone quiet. This never calls any Connect/ChatJS
// API - the widget only has a CUSTOMER participant connection, so it has no
// way to make the bot/agent genuinely speak again. Instead this makes a
// fresh local copy of their last message (new id, new sentTime) and feeds
// it back through the normal transcript pipeline, so it appears as a new
// bubble in THIS customer's view only - nothing is sent anywhere, and
// nothing changes on the transcript any agent/the bot sees.
// A new id (rather than reusing the original) matters here: _addItemsToTranscript
// keys new items by id, so reusing the same id would just re-sort the
// existing bubble in place instead of adding a visibly new one. The
// transportDetails object is spread into a NEW object (not mutated) so the
// original message in the transcript is left untouched.
function cloneIncomingItemForReprompt(item) {
  const clonedItem = new ItemDetails(item);
  clonedItem.id = _generateLocalId();
  clonedItem.transportDetails = {
    ...item.transportDetails,
    status: Status.SendSuccess,
    sentTime: _timestampNow(),
  };
  // Flagged so ChatTranscriptor's avatar-grouping always gives this its own
  // avatar bubble instead of folding it into the previous message's group -
  // see isLocalNotice handling in ChatTranscriptor.avatarGroupKey.
  clonedItem.isLocalNotice = true;
  return clonedItem;
}

// Same "local-only, never sent anywhere" rules as cloneIncomingItemForReprompt
// above, but for a brand new piece of text (the inactivity flow's "Sorry, I
// didn't get your response."/"Thank you for connecting with us today."
// notices) rather than a copy of an existing message. Reuses referenceItem's
// participantId/participantRole/displayName so the notice still visually
// reads as coming from whoever was last speaking (the bot/agent), just with
// fresh content, id, and timestamp.
function createLocalIncomingNotice(referenceItem, text) {
  const clonedItem = new ItemDetails(referenceItem);
  clonedItem.id = _generateLocalId();
  clonedItem.type = PARTICIPANT_MESSAGE;
  clonedItem.content = {data: text, type: ContentType.MESSAGE_CONTENT_TYPE.TEXT_PLAIN};
  clonedItem.transportDetails = {
    ...referenceItem.transportDetails,
    status: Status.SendSuccess,
    sentTime: _timestampNow(),
  };
  // See cloneIncomingItemForReprompt above - same reasoning applies here.
  clonedItem.isLocalNotice = true;
  return clonedItem;
}

function _generateLocalId() {
  var dt = new Date().getTime();
  var uuid = "xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx".replace(/[xy]/g, function(
    c
  ) {
    var r = (dt + Math.random() * 16) % 16 | 0;
    dt = Math.floor(dt / 16);
    return (c === "x" ? r : (r & 0x3) | 0x8).toString(16);
  });
  return uuid;
}

function _timestampNow() {
  var date = new Date();
  var timestamp = date.getTime();
  return timestamp / 1000;
}

function createTypingParticipant(typingDataItem, thisParticipantId) {
  var participantTypingDetails = {};
  participantTypingDetails.participantId = typingDataItem.ParticipantId;
  participantTypingDetails.displayName = typingDataItem.DisplayName;
  var direction =
    thisParticipantId === typingDataItem.ParticipantId
      ? Direction.Outgoing
      : Direction.Incoming;
  participantTypingDetails.direction = direction;
  return participantTypingDetails;
}

function isAttachmentContentType(contentType) {
  return contentType && Object.values(ContentType.ATTACHMENT_CONTENT_TYPE).includes(contentType.toLowerCase());
}

// The real attachment metadata (AttachmentId/ContentType/Status/AttachmentName)
// only exists once the item has round-tripped through the transcript API -
// a just-sent (not yet echoed back) outgoing attachment only has the raw
// File object on .content, so fall back to that file's own name/type.
function getAttachmentContentAndType(itemDetails) {
  if (itemDetails.Attachments && itemDetails.Attachments.length > 0) {
    const content = itemDetails.Attachments[0];
    return {content, contentType: content.ContentType};
  }
  return {
    content: {AttachmentName: itemDetails.content && itemDetails.content.name},
    contentType: itemDetails.content && itemDetails.content.type,
  };
}

// Only an outgoing (customer-sent) image/video attachment is grouped into
// the multi-image grid bubble (see ChatTranscriptor) - incoming attachments
// keep their existing one-bubble-per-attachment treatment so per-message
// read-receipt tracking (which keys off the single rendered item's id) is
// unaffected.
function isMediaAttachmentItem(itemDetails) {
  if (itemDetails.type !== ATTACHMENT_MESSAGE) {
    return false;
  }
  if (!itemDetails.transportDetails || itemDetails.transportDetails.direction !== Direction.Outgoing) {
    return false;
  }
  const {contentType} = getAttachmentContentAndType(itemDetails);
  return !!contentType && (contentType.startsWith("image/") || contentType.startsWith("video/"));
}

// An outgoing (customer-sent) attachment the server rejected on
// content-guideline / moderation grounds - its Attachments[0].Status is
// REJECTED, which ChatMessage surfaces to the customer as the "upload has
// been blocked" guidance (see AttachmentStatus.REJECTED branch there).
function isRejectedAttachmentMessage(itemDetails) {
  if (!itemDetails || itemDetails.type !== ATTACHMENT_MESSAGE) {
    return false;
  }
  if (!itemDetails.transportDetails || itemDetails.transportDetails.direction !== Direction.Outgoing) {
    return false;
  }
  const attachment = itemDetails.Attachments && itemDetails.Attachments[0];
  return !!attachment && attachment.Status === AttachmentStatus.REJECTED;
}

// Decides whether the composer should keep the paperclip open for another
// try after a rejected upload. Returns true while the newest outgoing
// attachment in the transcript is a rejection AND the customer still has
// re-upload attempts left (rejections so far <= maxReuploadAttempts). A
// later compliant upload makes the newest attachment a non-rejection, which
// closes this again on its own; burning through the allowed re-attempts
// keeps it closed. A no-op (returns false) for any transcript with no
// rejected attachment, so existing attachment behaviour is unchanged.
function shouldAllowAttachmentReupload(transcript, maxReuploadAttempts) {
  if (!Array.isArray(transcript)) {
    return false;
  }
  let rejectedCount = 0;
  let newestOutgoingAttachmentRejected = false;
  let sawOutgoingAttachment = false;
  for (let i = 0; i < transcript.length; i++) {
    const item = transcript[i];
    if (
      !item ||
      item.type !== ATTACHMENT_MESSAGE ||
      !item.transportDetails ||
      item.transportDetails.direction !== Direction.Outgoing
    ) {
      continue;
    }
    sawOutgoingAttachment = true;
    const rejected = isRejectedAttachmentMessage(item);
    newestOutgoingAttachmentRejected = rejected;
    if (rejected) {
      rejectedCount++;
    }
  }
  return sawOutgoingAttachment && newestOutgoingAttachmentRejected && rejectedCount <= maxReuploadAttempts;
}

function createIncomingTranscriptReceiptItem(thisParticipant, oldItemInTranscript, messageReceiptData, messageReceiptType) {
  const newTranscriptItem = new ItemDetails();
  Object.assign(newTranscriptItem, oldItemInTranscript);

  newTranscriptItem.transportDetails = {
    ...oldItemInTranscript.transportDetails,
    messageReceiptType: oldItemInTranscript.transportDetails.messageReceiptType === "read" ? "read" : messageReceiptType,
  };
  return newTranscriptItem;
}

function isTypeMessageOrAttachment(type) {
  return (type === PARTICIPANT_MESSAGE || type === ATTACHMENT_MESSAGE);
}

function isParticipantAgentOrCustomer(participantRole) {
  return (participantRole === PARTICIPANT_TYPES.CUSTOMER || participantRole === PARTICIPANT_TYPES.AGENT);
}

/**
 * A utility function to parse depth of 1 fields in the partially parsed view input data.
 *
 * @param {ViewInputData} parsedViewInputData - the partially parsed view input data
 * @returns {ViewInputData} the fully parsed view input data
 */
function fullyParseViewInputData(parsedViewInputData) {
  let fullyParsedViewInputData = {};
  Object.entries(parsedViewInputData).forEach(([key, value]) => {
    /**
     * There are two valid cases here: value is a string or an object.
     * In the cases that it is an object or an unparsable string, JSON.parse will throw.
     * In those cases, we will let the renderer see the raw value and determine whether it's the right format.
     * If it is in fact a valid stringified object, we will pass the parsed object to the renderer.
     */
    try {
      fullyParsedViewInputData[key] = JSON.parse(value);
    } catch (e) {
      fullyParsedViewInputData[key] = value;
    }
  });
  return fullyParsedViewInputData;
}

function createViewMessageData(data) {
  try {
    let parsedViewInputData = typeof data.content.viewData === "string" ? JSON.parse(data.content.viewData) : data.content.viewData;
    const outputViewData = {
      viewId: data.content.viewId,
      viewToken: data.content.viewToken,
      viewInputData: fullyParseViewInputData(parsedViewInputData)
    }
    return outputViewData;
  } catch (err) {
    console.warn("ERROR", err, data);
  }
}

function isViewMessage(message) {
  try {
    return message.content && message.content.data &&
      JSON.parse(message.content.data).templateType === InteractiveMessageType.VIEW_RESOURCE &&
      (
        message.content.type === ContentType.MESSAGE_CONTENT_TYPE.INTERACTIVE_MESSAGE ||
        message.content.type === ContentType.MESSAGE_CONTENT_TYPE.INTERACTIVE_RESPONSE
      );
  } catch (e) {
    return false;
  }
}

// QuickReply is the only interactive template whose CTA buttons should lock
// the composer's free-text input - other templates (ListPicker links,
// ViewResource forms, etc.) don't guarantee a response ever comes back
// (e.g. hyperlink options), which would leave the composer stuck disabled.
// Matches both a native Lex-sent interactive message and the same JSON sent
// as text/plain by a custom-bot Lambda (see isInteractiveMessagePayload in
// ChatMessage.js for the same dual-shape handling).
function isPendingQuickReplyMessage(message) {
  try {
    if (!message.content || typeof message.content.data !== "string") {
      return false;
    }
    const parsed = JSON.parse(message.content.data);
    if (parsed.templateType !== InteractiveMessageType.QUICK_REPLY) {
      return false;
    }
    return (
      message.content.type === ContentType.MESSAGE_CONTENT_TYPE.INTERACTIVE_MESSAGE ||
      (typeof parsed.data === "object" && parsed.data !== null &&
        typeof parsed.data.content === "object" && parsed.data.content !== null)
    );
  } catch (e) {
    return false;
  }
}

// The paperclip icon stays hidden until the bot's current step explicitly
// asks for a file - set via `attachmentExpected: true` alongside the
// existing title/elements fields in the interactive message's `content`
// object (data.content), the same envelope used by QuickReply/Panel/etc.
// Works for any templateType (a step can ask for a file alongside buttons,
// or on its own), and for both a native Lex-sent interactive message and the
// same JSON sent as text/plain by a custom-bot Lambda.
function isAttachmentExpectedMessage(message) {
  try {
    if (!message.content || typeof message.content.data !== "string") {
      return false;
    }
    const parsed = JSON.parse(message.content.data);
    const isInteractiveShaped =
      message.content.type === ContentType.MESSAGE_CONTENT_TYPE.INTERACTIVE_MESSAGE ||
      (typeof parsed.data === "object" && parsed.data !== null &&
        typeof parsed.data.content === "object" && parsed.data.content !== null);
    return isInteractiveShaped && parsed.data.content.attachmentExpected === true;
  } catch (e) {
    return false;
  }
}

var modelUtils = {
  createItemFromIncoming: createItemFromIncoming,
  createOutgoingTranscriptItem: createOutgoingTranscriptItem,
  createFailedItem: createFailedItem,
  cloneIncomingItemForReprompt: cloneIncomingItemForReprompt,
  createLocalIncomingNotice: createLocalIncomingNotice,
  createTypingParticipant: createTypingParticipant,
  isRecognizedEvent: isRecognizedEvent,
  createTranscriptItemFromSuccessResponse: createTranscriptItemFromSuccessResponse,
  isAttachmentContentType: isAttachmentContentType,
  getAttachmentContentAndType: getAttachmentContentAndType,
  isMediaAttachmentItem: isMediaAttachmentItem,
  isRejectedAttachmentMessage: isRejectedAttachmentMessage,
  shouldAllowAttachmentReupload: shouldAllowAttachmentReupload,
  createIncomingTranscriptReceiptItem: createIncomingTranscriptReceiptItem,
  isTypeMessageOrAttachment: isTypeMessageOrAttachment,
  isParticipantAgentOrCustomer: isParticipantAgentOrCustomer,
  createViewMessageData: createViewMessageData,
  isViewMessage: isViewMessage,
  isPendingQuickReplyMessage: isPendingQuickReplyMessage,
  isAttachmentExpectedMessage: isAttachmentExpectedMessage,
};

export {modelUtils};
